const CUADERNO = { c13: 'P1.2', c22: 'P1.1 y P1.3', c14: 'P2.3', c23: 'P2.2', c15: 'P3', c16: 'P4.1 y P4.3', c24: 'P4.2', c11: 'P5.1', c25: 'P5.3', c26: 'P6', c8: 'P7.1 y P7.2', c9: 'P7.3', c27: 'P8', c19: 'P9.1', c28: 'P10', c20: 'P11.1', c29: 'P11.2', c12: 'P12', c21: 'P12' };
{
  const orden = TEMAS.flatMap((t) => t.ids);
  PRACTICES.sort((a, b) => orden.indexOf(a.id) - orden.indexOf(b.id));
  PRACTICES.forEach((p, i) => { p.n = i + 1; p.tema = TEMAS.find((t) => t.ids.includes(p.id))?.tema || null; if (CUADERNO[p.id]) p.cuaderno = CUADERNO[p.id]; });
}
